import { Hono } from 'hono';
import { jwt, sign } from 'hono/jwt';

const app = new Hono<{ Bindings: { {{secret_env}}: string } }>();

app.post('/login', async (c) => {
  const { username } = await c.req.json();
  const token = await sign({ sub: username, exp: Math.floor(Date.now() / 1000) + 3600 }, c.env.{{secret_env}});
  return c.json({ token });
});

app.use('/api/*', (c, next) => jwt({ secret: c.env.{{secret_env}} })(c, next));
app.get('/api/me', (c) => c.json({ user: c.get('jwtPayload') }));

export default app;
